import std/json (decode, Json, JNull, JBool, JNumber, JString, JArray, JObject)

type Config = {
  app_name: string,
  version: string,
  port: int,
  features: List[string]
}

func validatePort(port: int) -> bool =
  port >= 1024 && port <= 65535

func countDots(s: string, i: int) -> int =
  if i >= _str_len(s)
  then 0
  else {
    let c = _str_char_at(s, i) in
    (if _str_eq(c, ".") then 1 else 0) + countDots(s, i + 1)
  }

func validateVersion(ver: string) -> bool =
  countDots(ver, 0) == 2

func findKey(kvs: List[{key: string, value: Json}], target: string) -> Json =
  match kvs {
    [] => JNull,
    kv :: rest =>
      if _str_eq(kv.key, target) then kv.value else findKey(rest, target)
  }

func loadConfig(filename: string) -> Config ! {FS} =
  let content = readFile(filename) in
  match decode(content) {
    Ok(JObject(kvs)) => {
      let appNameJson = findKey(kvs, "app_name");
      let versionJson = findKey(kvs, "version");
      let portJson = findKey(kvs, "port");
      let featuresJson = findKey(kvs, "features");

      let app_name =
        match appNameJson {
          JString(s) => s,
          _ => "Unknown"
        };

      let version =
        match versionJson {
          JString(s) => s,
          _ => "0.0.0"
        };

      let port =
        match portJson {
          JNumber(f) => floatToInt(f),
          _ => 0
        };

      let features =
        match featuresJson {
          JArray(js) =>
            match js {
              [] => [],
              _ =>
                letrec convert = \xs.
                  match xs {
                    [] => [],
                    j :: rest =>
                      match j {
                        JString(s) => s :: convert(rest),
                        _ => convert(rest)
                      }
                  } in
                convert(js)
            },
          _ => []
        };

      if validatePort(port) && validateVersion(version) && (! _str_eq(show(_list_length(features)), "0"))
      then {app_name: app_name, version: version, port: port, features: features}
      else {app_name: "Invalid", version: "0.0.0", port: 0, features: []}
    },
    _ => {app_name: "Invalid", version: "0.0.0", port: 0, features: []}
  }

func countList[a](xs: List[a]) -> int =
  match xs {
    [] => 0,
    _ :: rest => 1 + countList(rest)
  }

export func main() -> () ! {IO, FS} {
  let jsonText = "{\"app_name\":\"MyApp\",\"version\":\"1.0.0\",\"port\":8080,\"features\":[\"logging\",\"auth\",\"api\"]}" in
  let _ = writeFile("app_config.json", jsonText) in
  let cfg = loadConfig("app_config.json") in
  let n = countList(cfg.features) in
  println("Loaded " ++ cfg.app_name ++ " v" ++ cfg.version ++ " on port " ++ show(cfg.port) ++ " with " ++ show(n) ++ " features")
}

