module benchmark/solution

import std/io (println)
import std/fs (readFile, writeFile)
import std/json (encode, Json, jo, kv, js, jnum)
import std/string (split, stringToInt, _str_contains)
import std/option (Option, Some, None)
import std/list (reverse) -- For reversing list built by fold/recursion

-- Define the User record type for structured data
export type User = { name: string, age: int, email: string }

-- Helper function to create the initial CSV file
func createInputCsv(filename: string) -> () ! {FS, IO} {
  let csvContent =
    "name,age,email\n" ++
    "Alice,30,alice@example.com\n" ++
    "Bob,25,bob@example.com\n" ++
    "Carol,35,carol@example.com\n" ++
    "David,-5,david@example.com\n" ++       -- Invalid age (negative)
    "Eve,abc,eveexample.com\n" ++         -- Invalid age (not int) and email (no @)
    "Frank,40,frank@example.com"
  ;
  writeFile(filename, csvContent);
  println("Created " ++ filename)
}

-- Function to parse a CSV line into a list of strings by splitting on comma
func parseCsvLine(line: string) -> List[string] {
  split(line, ",")
}

-- Function to validate a single row of string fields and convert it to an Option[User]
-- Returns Some(User) if valid, None otherwise.
func validateAndBuildUser(row: List[string]) -> Option[User] {
  match row {
    [name, ageStr, email] =>
      match stringToInt(ageStr) {
        Some(age) =>
          if age > 0 && _str_contains(email, "@")
          then Some({name: name, age: age, email: email})
          else None,
        None => None -- Age is not a valid integer
      },
    _ => None -- Row does not have exactly 3 columns
  }
}

-- Recursive function to process a list of CSV rows, validate them,
-- and collect all valid User records into a new list.
func collectValidUsers(rows: List[List[string]], acc: List[User]) -> List[User] {
  match rows {
    [] => reverse(acc), -- Reverse to maintain original order as we cons onto acc
    row :: rest =>
      match validateAndBuildUser(row) {
        Some(user) => collectValidUsers(rest, user :: acc),
        None => collectValidUsers(rest, acc)
      }
  }
}

-- Function to convert a User record into a JSON object (Json ADT type)
func userToJson(user: User) -> Json {
  jo([
    kv("name", js(user.name)),
    kv("age", jnum(intToFloat(user.age))), -- Convert int to float for JSON number
    kv("email", js(user.email))
  ])
}

-- Main function to orchestrate CSV to JSON conversion
export func main() -> () ! {IO, FS} {
  let inputFilename = "users.csv";
  let outputFilename = "users.json";

  -- 1. Create the input CSV file
  createInputCsv(inputFilename);

  -- 2. Read the CSV file content
  let csvContent = readFile(inputFilename);
  println("Read " ++ inputFilename);

  -- Split content into lines, then remove the header line
  let lines = split(csvContent, "\n");
  let dataLines = match lines {
    [] => [],
    _ :: rest => rest -- Skip the first line (header)
  };

  -- Filter out any empty lines that might result from trailing newlines
  let nonEmptyDataLines = filter(\line. length(line) > 0, dataLines);

  -- Parse each non-empty data line into a List[string] (row)
  let parsedRows = map(parseCsvLine, nonEmptyDataLines);

  -- 3. Validate each row and collect valid users
  let validUsers = collectValidUsers(parsedRows, []);

  let validRowCount = length(validUsers);
  println("Validated " ++ show(validRowCount) ++ " rows.");

  -- 4. Convert the list of valid User records to a List[Json] objects
  let jsonUsers = map(userToJson, validUsers);

  -- Wrap the list of JSON objects into a single JSON array, then encode to string
  let finalJsonArray = Json.JArray(jsonUsers);
  let finalJsonString = encode(finalJsonArray);

  -- 5. Write the JSON string to "users.json" file
  writeFile(outputFilename, finalJsonString);
  println("Wrote JSON to " ++ outputFilename);

  -- 6. Print the final message to stdout
  println("Converted " ++ show(validRowCount) ++ " valid rows to " ++ outputFilename)
}

-- Helper functions for std/list and filter (as std/list isn't auto-imported entirely)
-- This assumes std/list map and filter aren't automatically available without import,
-- but the main function is written to use them from std/list.
-- If map/filter are not explicitly imported, these custom definitions would be needed.
-- For this exercise, I'll rely on the `import std/list (map, filter)` for these functions.
-- Adding reverse because it was used from std/list.

func map[a, b](f: a -> b, xs: List[a]) -> List[b] {
  match xs {
    [] => [],
    x :: rest => f(x) :: map(f, rest)
  }
}

func filter[a](pred: a -> bool, xs: List[a]) -> List[a] {
  match xs {
    [] => [],
    x :: rest =>
      if pred(x)
      then x :: filter(pred, rest)
      else filter(pred, rest)
  }
}

