from typing import TypeVar, Generic, Callable

T = TypeVar('T')
A = TypeVar('A')
B = TypeVar('B')

class Pure(Generic[T]):
    """Wrapper for pure values - can only be created by pure functions"""
    def __init__(self, value: T):
        self._value = value

    def run(self) -> T:
        return self._value

class IO(Generic[T]):
    """Wrapper for effectful computations"""
    def __init__(self, effect: Callable[[], T]):
        self._effect = effect

    def run(self) -> T:
        return self._effect()

# PURE functions - return Pure wrapper
def double(x: int) -> Pure[int]:
    """Pure function: doubles a number"""
    return Pure(x * 2)

def add(a: int, b: int) -> Pure[int]:
    """Pure function: adds two numbers"""
    return Pure(a + b)

# EFFECTFUL functions - return IO wrapper
def printResult(label: str, value: int) -> IO[None]:
    """Effectful function: prints label and value"""
    def effect():
        print(f"{label}: {value}")
    return IO(effect)

def compute_and_print() -> IO[None]:
    """Effectful function: computes using pure functions and prints result"""
    def effect():
        # Call pure functions and extract values
        result1 = double(5).run()
        result2 = add(result1, 3).run()
        # Call effectful function
        printResult("Result", result2).run()
    return IO(effect)

if __name__ == "__main__":
    # Run the effectful computation
    compute_and_print().run()

