import sys
from typing import Generic, TypeVar, Union

T = TypeVar('T')

class Ok(Generic[T]):
    """Represents a successful result with a value."""
    def __init__(self, value: T) -> None:
        self.value = value

    def __repr__(self) -> str:
        return f"Ok({self.value!r})"

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Ok):
            return NotImplemented
        return self.value == other.value

class Err:
    """Represents a failed result with an error message."""
    def __init__(self, message: str) -> None:
        self.message = message

    def __repr__(self) -> str:
        return f"Err({self.message!r})"

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Err):
            return NotImplemented
        return self.message == other.message

# Define the Result type as a Union of Ok and Err
Result = Union[Ok[T], Err]

def parse_int(s: str) -> Result[int]:
    """
    Attempts to parse a string into an integer.

    Returns Ok(n) if successful, or Err("Invalid integer") otherwise.
    """
    try:
        return Ok(int(s))
    except ValueError:
        return Err("Invalid integer")

def divide_safe(a: int, b: int) -> Result[int]:
    """
    Divides two integers safely, preventing division by zero.

    Returns Ok(a/b) if b is not zero, or Err("Division by zero") otherwise.
    Performs integer division.
    """
    if b == 0:
        return Err("Division by zero")
    return Ok(a // b)

def main() -> None:
    """
    Runs the test cases for parsing integers and safe division.
    """
    # Test case 1: parse_int("10") then divide by 2 -> "Result: 5"
    result_1: Result[int]
    parsed_val_1 = parse_int("10")
    if isinstance(parsed_val_1, Ok):
        result_1 = divide_safe(parsed_val_1.value, 2)
    else:
        result_1 = parsed_val_1  # Propagate the Err

    if isinstance(result_1, Ok):
        print(f"Result: {result_1.value}")
    else:
        print(f"Error: {result_1.message}")

    # Test case 2: parse_int("10") then divide by 0 -> "Error: Division by zero"
    result_2: Result[int]
    parsed_val_2 = parse_int("10")
    if isinstance(parsed_val_2, Ok):
        result_2 = divide_safe(parsed_val_2.value, 0)
    else:
        result_2 = parsed_val_2  # Propagate the Err

    if isinstance(result_2, Ok):
        print(f"Result: {result_2.value}")
    else:
        print(f"Error: {result_2.message}")

    # Test case 3: parse_int("abc") -> "Error: Invalid integer"
    result_3: Result[int] = parse_int("abc")
