module benchmark/solution

import std/io (readFile, writeFile, println)
import std/string (split, substring, length, indexOf, contains)
import std/list (map, filter, foldl, reverse)
import std/option (Option, Some, None)

type LogEntry = {
  timestamp: string,
  level: string,
  message: string
}

type LogStats = {
  total: int,
  info_count: int,
  error_count: int,
  warning_count: int,
  users: List[string]
}

-- Helper function to join a list of strings with a separator
func joinStrings(sep: string, xs: List[string]) -> string {
  match xs {
    [] => "",
    [x] => x,
    x :: rest => x ++ sep ++ joinStrings(sep, rest)
  }
}

-- Helper to split string (using std/string.split)
-- func split(s: string, delim: string) -> List[string] (already in std/string)

-- Helper to get substring after a given search string
func getSubstringAfter(mainStr: string, searchStr: string) -> Option[string] {
  match indexOf(mainStr, searchStr) {
    Some(idx) => Some(substring(mainStr, idx + length(searchStr), length(mainStr) - (idx + length(searchStr)))),
    None => None
  }
}

-- Helper to parse a log line
func parseLogLine(line: string) -> LogEntry {
  let parts = split(line, " ");
  match parts {
    [date, time, level, ...rest] => {
      let timestamp = date ++ " " ++ time;
      let message = joinStrings(" ", rest);
      { timestamp: timestamp, level: level, message: message }
    },
    _ => { timestamp: "UNKNOWN", level: "UNKNOWN", message: line } -- Fallback for malformed lines
  }
}

-- Helper to extract users from message (look for "User logged in: user" or "User logged out: user")
func extractUser(message: string) -> Option[string] {
  match getSubstringAfter(message, "User logged in: ") {
    Some(user) => Some(user),
    None => match getSubstringAfter(message, "User logged out: ") {
      Some(user) => Some(user),
      None => None
    }
  }
}

-- Helper to check if a string is present in a list of strings
func containsString(target: string, xs: List[string]) -> bool {
  match xs {
    [] => false,
    x :: rest => if x == target then true else containsString(target, rest)
  }
}

-- Helper to add a user to a list only if not already present
func addUniqueUser(user: string, userList: List[string]) -> List[string] {
  if containsString(user, userList) then userList else user :: userList
}

-- Accumulator type for log analysis
type LogStatsAccumulator = {
  total: int,
  info_count: int,
  error_count: int,
  warning_count: int,
  users: List[string] -- Users collected in reverse order of appearance, potentially with duplicates to be removed/sorted later
}

-- Function to update statistics for a single log entry
func updateStats(entry: LogEntry, acc: LogStatsAccumulator) -> LogStatsAccumulator {
  let new_info = if entry.level == "INFO" then acc.info_count + 1 else acc.info_count;
  let new_error = if entry.level == "ERROR" then acc.error_count + 1 else acc.error_count;
  let new_warning = if entry.level == "WARNING" then acc.warning_count + 1 else acc.warning_count;

  let user_option = extractUser(entry.message);
  let new_users = match user_option {
    Some(user) => addUniqueUser(user, acc.users),
    None => acc.users
  };

  {
    total: acc.total + 1,
    info_count: new_info,
    error_count: new_error,
    warning_count: new_warning,
    users: new_users
  }
}

-- Helper to calculate percentage
func percentage(count: int, total: int) -> int {
  if total == 0 then 0 else (count * 100) / total
}

func analyzeLog(filename: string) -> LogStats ! {FS} {
  let content = readFile(filename);
  let rawLines = split(content, "\n");
  let non_empty_lines = filter(\line. length(line) > 0, rawLines);
  let entries = map(parseLogLine, non_empty_lines);

  let initialStats = { total: 0, info_count: 0, error_count: 0, warning_count: 0, users: [] };
  let finalAccumulatedStats = foldl(updateStats, initialStats, entries);

  -- `addUniqueUser` prepends, so reversing the list puts it in order of first appearance.
  -- For "alice, bob" in the output, it implies sorted alphabetically or by first occurrence.
  -- Since alice logs in first, then bob, this will result in ["alice", "bob"] after reverse.
  let uniqueUsersOrdered = reverse(finalAccumulatedStats.users);

  {
    total: finalAccumulatedStats.total,
    info_count: finalAccumulatedStats.info_count,
    error_count: finalAccumulatedStats.error_count,
    warning_count: finalAccumulatedStats.warning_count,
    users: uniqueUsersOrdered
  }
}

export func main() -> () ! {IO, FS} {
  let logContent = "2024-10-29 10:00:00 INFO User logged in: alice\n2024-10-29 10:01:15 ERROR Database connection failed\n2024-10-29 10:02:30 INFO User logged in: bob\n2024-10-29 10:03:45 WARNING High memory usage: 85%\n2024-10-29 10:05:00 ERROR API timeout: /users endpoint\n2024-10-29 10:06:15 INFO User logged out: alice";
  let _ = writeFile("app.log", logContent);

  let stats = analyzeLog("app.log");

  let _ = println("Total log entries: " ++ show(stats.total));
  let _ = println("INFO: " ++ show(stats.info_count) ++ " (" ++ show(percentage(stats.info_count, stats.total)) ++ "%)");
  let _ = println("ERROR: " ++ show(stats.error_count) ++ " (" ++ show(percentage(stats.error_count, stats.total)) ++ "%)");
  let _ = println("WARNING: " ++ show(stats.warning_count) ++ " (" ++ show(percentage(stats.warning_count, stats.total)) ++ "%)");

  let user_list_str = joinStrings(", ", stats.users);
  println("Unique users: " ++ user_list_str)
}

