from dataclasses import dataclass
from typing import Union

@dataclass
class Leaf:
    value: int

@dataclass
class Node:
    left: 'Tree'
    value: int
    right: 'Tree'

Tree = Union[Leaf, Node]

def tree_sum(tree: Tree) -> int:
    match tree:
        case Leaf(v):
            return v
        case Node(l, v, r):
            return tree_sum(l) + v + tree_sum(r)

def find_max(tree: Tree) -> int:
    match tree:
        case Leaf(v):
            return v
        case Node(l, v, r):
            left_max = find_max(l)
            right_max = find_max(r)
            return max(left_max, v, right_max)

def main():
    tree = Node(Leaf(1), 5, Node(Leaf(3), 7, Leaf(2)))
    sum_result = tree_sum(tree)
    max_result = find_max(tree)
    print(f"Sum: {sum_result}")
    print(f"Max: {max_result}")

