type State = Green(int) | Yellow(int) | Red(int)
type Event = Tick | Reset

func transition(s: State, e: Event) -> State {
  match s {
    Green(n) => match e {
      Tick => if n > 1 then Green(n - 1) else Yellow(3),
      Reset => Green(20)
    },
    Yellow(n) => match e {
      Tick => if n > 1 then Yellow(n - 1) else Red(10),
      Reset => Green(20)
    },
    Red(n) => match e {
      Tick => if n > 1 then Red(n - 1) else Green(20),
      Reset => Green(20)
    }
  }
}

func display(s: State) -> string {
  match s {
    Green(n) => "GREEN (" ++ show(n) ++ "sec)",
    Yellow(n) => "YELLOW (" ++ show(n) ++ "sec)",
    Red(n) => "RED (" ++ show(n) ++ "sec)"
  }
}

export func loopTicks(s: State, n: int) -> State ! {IO} {
  if n <= 0
  then s
  else {
    let s2 = transition(s, Tick);
    println(display(s2));
    loopTicks(s2, n - 1)
  }
}

export func main() -> () ! {IO} {
  let start = Green(20);
  let after25 = loopTicks(start, 25);
  let afterReset = transition(after25, Reset);
  println(display(afterReset));
  let _ = loopTicks(afterReset, 5);
  ()
}

