from dataclasses import dataclass
from typing import Union

@dataclass(frozen=True)
class Green:
    timer: int

@dataclass(frozen=True)
class Yellow:
    timer: int

@dataclass(frozen=True)
class Red:
    timer: int

State = Union[Green, Yellow, Red]

@dataclass(frozen=True)
class Tick:
    pass

@dataclass(frozen=True)
class Reset:
    pass

Event = Union[Tick, Reset]

def transition(state: State, event: Event) -> State:
    match state, event:
        case _, Reset():
            return Green(20)

        case Green(timer=t), Tick():
            if t > 1:
                return Green(t - 1)
            return Yellow(3)

        case Yellow(timer=t), Tick():
            if t > 1:
                return Yellow(t - 1)
            return Red(10)

        case Red(timer=t), Tick():
            if t > 1:
                return Red(t - 1)
            return Green(20)

        case _:
            # Fallback for type checkers, though logic covers all cases
            return state

def display(state: State) -> str:
    match state:
        case Green(t):
            return f"GREEN ({t}sec)"
        case Yellow(t):
            return f"YELLOW ({t}sec)"
        case Red(t):
            return f"RED ({t}sec)"

def main() -> None:
    # Initial state
    state: State = Green(20)

    # Apply 25 Tick events
    for _ in range(25):
        state = transition(state, Tick())
        print(display(state))

    # Apply 1 Reset event
    state = transition(state, Reset())
    print(display(state))

    # Apply 5 Tick events
    for _ in range(5):
        state = transition(state, Tick())
        print(display(state))

if __name__ == "__main__":
    main()

