module benchmark/solution

import std/io (println)

type Tree =
  | Leaf(int)
  | Node(Tree, int, Tree)

export func mapTree(fn, tree) =
  match tree {
    Leaf(v) => Leaf(fn(v)),
    Node(left, v, right) => Node(mapTree(fn, left), fn(v), mapTree(fn, right))
  }

export func foldTree(fn, acc, tree) =
  match tree {
    Leaf(v) => fn(acc)(v),
    Node(left, v, right) => {
      let accLeft = foldTree(fn, acc, left);
      let accV = fn(accLeft)(v);
      foldTree(fn, accV, right)
    }
  }

export func append(xs, ys) =
  match xs {
    [] => ys,
    x :: rest => x :: append(rest, ys)
  }

export func treeToList(tree) =
  match tree {
    Leaf(v) => [v],
    Node(left, v, right) => {
      let leftList = treeToList(left);
      let rightList = treeToList(right);
      append(leftList, append([v], rightList))
    }
  }

export func filterNonZero(xs) =
  match xs {
    [] => [],
    x :: rest =>
      if x == 0
      then filterNonZero(rest)
      else x :: filterNonZero(rest)
  }

export func treeDepth(tree) =
  match tree {
    Leaf(_) => 1,
    Node(left, _, right) => {
      let leftDepth = treeDepth(left);
      let rightDepth = treeDepth(right);
      let maxDepth = if leftDepth > rightDepth then leftDepth else rightDepth;
      1 + maxDepth
    }
  }

export func showListHelper(xs) =
  match xs {
    [] => "",
    [x] => show(x),
    x :: rest => show(x) ++ ", " ++ showListHelper(rest)
  }

export func showList(xs) =
  "[" ++ showListHelper(xs) ++ "]"

export func main() -> () ! {IO} = {
  let tree = Node(
    Node(Leaf(1), 3, Leaf(0)),
    5,
    Node(Leaf(7), 8, Leaf(9))
  );

  let allValues = treeToList(tree);
  let original = filterNonZero(allValues);
  println("Original: " ++ showList(original));

  let doubled = mapTree(\x. x * 2, tree);
  let doubledList = filterNonZero(treeToList(doubled));
  println("Doubled: " ++ showList(doubledList));

  let sum = foldTree(\a. \b. a + b, 0, tree);
  println("Sum: " ++ show(sum));

  let depth = treeDepth(tree);
  println("Depth: " ++ show(depth))
}

